import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: [],
    include: ['src/**/*.test.{ts,tsx}'],
  },
  resolve: {
    alias: {
      '@': '/src',
    },
  },
});

export interface ClaimantInfo {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  dateOfBirth: string;
  address: string;
  city: string;
  postalCode: string;
}

export interface IncidentDetails {
  incidentDate: string;
  incidentTime: string;
  incidentType: 'auto' | 'property' | 'health' | 'other';
  description: string;
  location: string;
  policeReportFiled: boolean;
  policeReportNumber: string;
}

export interface AutoDamage {
  vehicleMake: string;
  vehicleModel: string;
  vehicleYear: string;
  licensePlate: string;
  damageDescription: string;
  otherVehicleInvolved: boolean;
  otherDriverInfo: string;
}

export interface PropertyDamage {
  propertyType: 'residential' | 'commercial' | 'other';
  damagedAreas: string[];
  estimatedLoss: string;
  occupantsPresent: boolean;
}

export interface HealthInjury {
  injuryType: string;
  bodyParts: string[];
  medicalAttention: boolean;
  facilityName: string;
  treatmentDate: string;
  ongoingTreatment: boolean;
}

export type DamageAssessment = AutoDamage | PropertyDamage | HealthInjury;

export interface UploadedFile {
  id: string;
  name: string;
  size: number;
  type: string;
  dataUrl: string;
}

export interface WitnessInfo {
  name: string;
  phone: string;
  email: string;
  relationship: string;
}

export interface SignatureData {
  dataUrl: string;
  signedAt: string;
}

export interface FormData {
  policyNumber: string;
  claimant: ClaimantInfo;
  incident: IncidentDetails;
  damage: DamageAssessment | null;
  documents: UploadedFile[];
  witnesses: WitnessInfo[];
  hasWitnesses: boolean;
  signature: SignatureData | null;
  agreedToTerms: boolean;
}

export type StepId =
  | 'welcome'
  | 'claimant'
  | 'incident'
  | 'damage'
  | 'documents'
  | 'witnesses'
  | 'review'
  | 'signature'
  | 'confirmation';

export interface StepConfig {
  id: StepId;
  title: string;
  description: string;
}

export interface ValidationError {
  field: string;
  message: string;
}

export interface FormState {
  data: FormData;
  currentStep: StepId;
  visitedSteps: Set<StepId>;
  validationErrors: ValidationError[];
  isSubmitting: boolean;
  submitSuccess: boolean;
}

export const DEFAULT_FORM_DATA: FormData = {
  policyNumber: '',
  claimant: {
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    dateOfBirth: '',
    address: '',
    city: '',
    postalCode: '',
  },
  incident: {
    incidentDate: '',
    incidentTime: '',
    incidentType: 'auto',
    description: '',
    location: '',
    policeReportFiled: false,
    policeReportNumber: '',
  },
  damage: null,
  documents: [],
  witnesses: [],
  hasWitnesses: false,
  signature: null,
  agreedToTerms: false,
};

export const STEPS: StepConfig[] = [
  { id: 'welcome', title: 'Get Started', description: 'Policy lookup' },
  { id: 'claimant', title: 'Your Details', description: 'Claimant information' },
  { id: 'incident', title: 'Incident', description: 'What happened' },
  { id: 'damage', title: 'Assessment', description: 'Damage details' },
  { id: 'documents', title: 'Documents', description: 'Supporting files' },
  { id: 'witnesses', title: 'Witnesses', description: 'Witness information' },
  { id: 'review', title: 'Review', description: 'Verify details' },
  { id: 'signature', title: 'Sign', description: 'Declaration' },
  { id: 'confirmation', title: 'Done', description: 'Submitted' },
];

export type FormAction =
  | { type: 'SET_FIELD'; path: string; value: unknown }
  | { type: 'SET_STEP_DATA'; step: StepId; data: Partial<FormData> }
  | { type: 'GO_TO_STEP'; step: StepId }
  | { type: 'NEXT_STEP'; availableSteps: StepId[] }
  | { type: 'PREV_STEP'; availableSteps: StepId[] }
  | { type: 'SET_VALIDATION_ERRORS'; errors: ValidationError[] }
  | { type: 'CLEAR_VALIDATION_ERRORS' }
  | { type: 'ADD_FILE'; file: UploadedFile }
  | { type: 'REMOVE_FILE'; fileId: string }
  | { type: 'ADD_WITNESS'; witness: WitnessInfo }
  | { type: 'REMOVE_WITNESS'; index: number }
  | { type: 'SET_SIGNATURE'; signature: SignatureData }
  | { type: 'SET_SUBMITTING'; isSubmitting: boolean }
  | { type: 'SET_SUBMIT_SUCCESS'; success: boolean }
  | { type: 'RESTORE_STATE'; state: FormState }
  | { type: 'RESET' }
  | { type: 'BATCH'; actions: FormAction[] };

export function deepSet(obj: Record<string, unknown>, path: string, value: unknown): Record<string, unknown> {
  const keys = path.split('.');
  const result = { ...obj };
  let current: Record<string, unknown> = result;

  for (let i = 0; i < keys.length - 1; i++) {
    const key = keys[i];
    if (!(key in current) || typeof current[key] !== 'object' || current[key] === null) {
      current[key] = {};
    } else if (Array.isArray(current[key])) {
      current[key] = [...(current[key] as unknown[])];
    } else {
      current[key] = { ...(current[key] as Record<string, unknown>) };
    }
    current = current[key] as Record<string, unknown>;
  }

  const lastKey = keys[keys.length - 1];
  current[lastKey] = value;
  return result;
}

export function deepGet(obj: Record<string, unknown>, path: string): unknown {
  const keys = path.split('.');
  let current: unknown = obj;

  for (const key of keys) {
    if (current === null || current === undefined) return undefined;
    if (typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[key];
  }

  return current;
}

export function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

export function isValidPhone(phone: string): boolean {
  return /^[\d\s\-\+\(\)]{7,20}$/.test(phone);
}

export function isValidPostalCode(code: string): boolean {
  return /^[A-Za-z0-9\s\-]{3,10}$/.test(code);
}

export function isValidDate(date: string): boolean {
  if (!date) return false;
  const d = new Date(date);
  return !isNaN(d.getTime());
}

export function isDateInPast(date: string): boolean {
  const d = new Date(date);
  const now = new Date();
  now.setHours(23, 59, 59, 999);
  return d <= now;
}

export function isNotEmpty(value: string): boolean {
  return value.trim().length > 0;
}

export function isPositiveNumber(value: string): boolean {
  return /^\d+(\.\d{1,2})?$/.test(value) && parseFloat(value) > 0;
}

const STORAGE_KEY = 'insurance_claim_wizard_draft';
const UNDO_HISTORY_KEY = 'insurance_claim_wizard_undo';
const REDO_HISTORY_KEY = 'insurance_claim_wizard_redo';
const VISITED_STEPS_KEY = 'insurance_claim_wizard_visited';

interface StoredState {
  data: unknown;
  currentStep: string;
  timestamp: number;
}

export function saveDraft(state: StoredState): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Storage full or unavailable
  }
}

export function loadDraft(): StoredState | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as StoredState;
  } catch {
    return null;
  }
}

export function clearDraft(): void {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    // ignore
  }
}

export function saveVisitedSteps(steps: string[]): void {
  try {
    localStorage.setItem(VISITED_STEPS_KEY, JSON.stringify(steps));
  } catch {
    // ignore
  }
}

export function loadVisitedSteps(): string[] {
  try {
    const raw = localStorage.getItem(VISITED_STEPS_KEY);
    if (!raw) return [];
    return JSON.parse(raw) as string[];
  } catch {
    return [];
  }
}

export function saveUndoHistory(state: StoredState[]): void {
  try {
    localStorage.setItem(UNDO_HISTORY_KEY, JSON.stringify(state.slice(-30)));
  } catch {
    // ignore
  }
}

export function loadUndoHistory(): StoredState[] {
  try {
    const raw = localStorage.getItem(UNDO_HISTORY_KEY);
    if (!raw) return [];
    return JSON.parse(raw) as StoredState[];
  } catch {
    return [];
  }
}

export function saveRedoHistory(state: StoredState[]): void {
  try {
    localStorage.setItem(REDO_HISTORY_KEY, JSON.stringify(state.slice(-30)));
  } catch {
    // ignore
  }
}

export function loadRedoHistory(): StoredState[] {
  try {
    const raw = localStorage.getItem(REDO_HISTORY_KEY);
    if (!raw) return [];
    return JSON.parse(raw) as StoredState[];
  } catch {
    return [];
  }
}

export function clearHistories(): void {
  try {
    localStorage.removeItem(UNDO_HISTORY_KEY);
    localStorage.removeItem(REDO_HISTORY_KEY);
    localStorage.removeItem(VISITED_STEPS_KEY);
  } catch {
    // ignore
  }
}

import { isValidEmail, isValidPhone, isNotEmpty, isValidDate, isDateInPast } from '../validation';
import type { FormData, ValidationError, StepId, DamageAssessment } from '../types';

export function validateStep(step: StepId, data: FormData): ValidationError[] {
  const errors: ValidationError[] = [];

  switch (step) {
    case 'welcome':
      if (!isNotEmpty(data.policyNumber)) {
        errors.push({ field: 'policyNumber', message: 'Policy number is required' });
      } else if (!/^[A-Za-z0-9]{6,20}$/.test(data.policyNumber)) {
        errors.push({ field: 'policyNumber', message: 'Policy number must be 6-20 alphanumeric characters' });
      }
      break;

    case 'claimant':
      if (!isNotEmpty(data.claimant.firstName)) {
        errors.push({ field: 'claimant.firstName', message: 'First name is required' });
      }
      if (!isNotEmpty(data.claimant.lastName)) {
        errors.push({ field: 'claimant.lastName', message: 'Last name is required' });
      }
      if (!isNotEmpty(data.claimant.email)) {
        errors.push({ field: 'claimant.email', message: 'Email is required' });
      } else if (!isValidEmail(data.claimant.email)) {
        errors.push({ field: 'claimant.email', message: 'Email format is invalid' });
      }
      if (isNotEmpty(data.claimant.phone) && !isValidPhone(data.claimant.phone)) {
        errors.push({ field: 'claimant.phone', message: 'Phone format is invalid' });
      }
      if (isNotEmpty(data.claimant.dateOfBirth) && !isValidDate(data.claimant.dateOfBirth)) {
        errors.push({ field: 'claimant.dateOfBirth', message: 'Date of birth is invalid' });
      }
      break;

    case 'incident':
      if (!isNotEmpty(data.incident.incidentDate)) {
        errors.push({ field: 'incident.incidentDate', message: 'Incident date is required' });
      } else if (!isValidDate(data.incident.incidentDate)) {
        errors.push({ field: 'incident.incidentDate', message: 'Incident date is invalid' });
      } else if (!isDateInPast(data.incident.incidentDate)) {
        errors.push({ field: 'incident.incidentDate', message: 'Incident date must be in the past' });
      }
      if (!isNotEmpty(data.incident.description)) {
        errors.push({ field: 'incident.description', message: 'Description is required' });
      }
      if (data.incident.policeReportFiled && !isNotEmpty(data.incident.policeReportNumber)) {
        errors.push({ field: 'incident.policeReportNumber', message: 'Police report number is required when filed' });
      }
      break;

    case 'damage': {
      const dmg = data.damage as DamageAssessment | null;
      if (!dmg) {
        errors.push({ field: 'damage', message: 'Damage details are required' });
        break;
      }
      if (data.incident.incidentType === 'auto') {
        const ad = dmg as Record<string, unknown>;
        if (!isNotEmpty(ad.vehicleMake as string)) {
          errors.push({ field: 'damage.vehicleMake', message: 'Vehicle make is required' });
        }
      } else if (data.incident.incidentType === 'property') {
        const pd = dmg as Record<string, unknown>;
        if (!pd.propertyType) {
          errors.push({ field: 'damage.propertyType', message: 'Property type is required' });
        }
      } else if (data.incident.incidentType === 'health') {
        const hi = dmg as Record<string, unknown>;
        if (!isNotEmpty(hi.injuryType as string)) {
          errors.push({ field: 'damage.injuryType', message: 'Injury type is required' });
        }
      }
      break;
    }

    case 'signature':
      if (!data.signature?.dataUrl) {
        errors.push({ field: 'signature', message: 'Signature is required' });
      }
      if (!data.agreedToTerms) {
        errors.push({ field: 'agreedToTerms', message: 'You must agree to the terms' });
      }
      break;
  }

  return errors;
}

export function isStepValid(step: StepId, data: FormData): boolean {
  return validateStep(step, data).length === 0;
}

import { createContext, useContext, useReducer, useCallback, useEffect, useRef } from 'react';
import type {
  FormState,
  FormAction,
  FormData,
  StepId,
  ValidationError,
  UploadedFile,
  WitnessInfo,
  SignatureData,
} from '../types';
import { DEFAULT_FORM_DATA, STEPS } from '../types';
import { validateStep } from '../validation/stepValidation';
import { deepSet } from '../utils/object';
import {
  saveDraft,
  loadDraft,
  clearDraft,
  saveVisitedSteps,
  loadVisitedSteps,
  saveUndoHistory,
  loadUndoHistory,
  saveRedoHistory,
  loadRedoHistory,
  clearHistories,
} from '../utils/storage';

interface FormContextValue {
  state: FormState;
  dispatch: React.Dispatch<FormAction>;
  goToStep: (step: StepId) => void;
  nextStep: () => void;
  prevStep: () => void;
  undo: () => void;
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  availableSteps: StepId[];
  currentStepIndex: number;
  setField: (path: string, value: unknown) => void;
  validateCurrentStep: () => ValidationError[];
}

function computeAvailableSteps(data: FormData): StepId[] {
  const steps: StepId[] = [];
  for (const step of STEPS) {
    if (step.id === 'witnesses' && !data.hasWitnesses) continue;
    steps.push(step.id);
  }
  return steps;
}

function formReducer(state: FormState, action: FormAction): FormState {
  switch (action.type) {
    case 'SET_FIELD': {
      const newData = deepSet(state.data as unknown as Record<string, unknown>, action.path, action.value) as unknown as FormData;
      return { ...state, data: newData };
    }
    case 'SET_STEP_DATA':
      return {
        ...state,
        data: { ...state.data, ...action.data },
      };
    case 'GO_TO_STEP':
      return {
        ...state,
        currentStep: action.step,
        visitedSteps: new Set([...state.visitedSteps, action.step]),
        validationErrors: [],
      };
    case 'NEXT_STEP': {
      const avail = action.availableSteps;
      const currentIdx = avail.indexOf(state.currentStep);
      const nextIdx = currentIdx + 1;
      if (nextIdx >= avail.length) return state;
      const nextStep = avail[nextIdx];
      return {
        ...state,
        currentStep: nextStep,
        visitedSteps: new Set([...state.visitedSteps, nextStep]),
        validationErrors: [],
      };
    }
    case 'PREV_STEP': {
      const availPrev = action.availableSteps;
      const currentIdxPrev = availPrev.indexOf(state.currentStep);
      const prevIdx = currentIdxPrev - 1;
      if (prevIdx < 0) return state;
      return {
        ...state,
        currentStep: availPrev[prevIdx],
        validationErrors: [],
      };
    }
    case 'SET_VALIDATION_ERRORS':
      return { ...state, validationErrors: action.errors };
    case 'CLEAR_VALIDATION_ERRORS':
      return { ...state, validationErrors: [] };
    case 'ADD_FILE':
      return {
        ...state,
        data: { ...state.data, documents: [...state.data.documents, action.file] },
      };
    case 'REMOVE_FILE':
      return {
        ...state,
        data: {
          ...state.data,
          documents: state.data.documents.filter((f) => f.id !== action.fileId),
        },
      };
    case 'ADD_WITNESS':
      return {
        ...state,
        data: { ...state.data, witnesses: [...state.data.witnesses, action.witness] },
      };
    case 'REMOVE_WITNESS':
      return {
        ...state,
        data: {
          ...state.data,
          witnesses: state.data.witnesses.filter((_, i) => i !== action.index),
        },
      };
    case 'SET_SIGNATURE':
      return { ...state, data: { ...state.data, signature: action.signature } };
    case 'SET_SUBMITTING':
      return { ...state, isSubmitting: action.isSubmitting };
    case 'SET_SUBMIT_SUCCESS':
      return { ...state, submitSuccess: action.success };
    case 'RESTORE_STATE':
      return {
        ...action.state,
        visitedSteps: new Set(action.state.visitedSteps),
        validationErrors: [],
      };
    case 'RESET':
      return {
        data: { ...DEFAULT_FORM_DATA },
        currentStep: 'welcome',
        visitedSteps: new Set(['welcome']),
        validationErrors: [],
        isSubmitting: false,
        submitSuccess: false,
      };
    case 'BATCH':
      return action.actions.reduce((s, a) => formReducer(s, a), state);
    default:
      return state;
  }
}

function createInitialState(): FormState {
  const saved = loadDraft();
  const visited = loadVisitedSteps();
  if (saved?.data) {
    return {
      data: saved.data as FormData,
      currentStep: 'welcome',
      visitedSteps: new Set(visited.length > 0 ? visited : ['welcome']),
      validationErrors: [],
      isSubmitting: false,
      submitSuccess: false,
    };
  }
  return {
    data: { ...DEFAULT_FORM_DATA },
    currentStep: 'welcome',
    visitedSteps: new Set(['welcome']),
    validationErrors: [],
    isSubmitting: false,
    submitSuccess: false,
  };
}

const FormContext = createContext<FormContextValue | null>(null);

export function FormProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(formReducer, undefined, createInitialState);

  const undoStack = useRef<FormState[]>(loadUndoHistory().map((s) => ({
    ...s,
    data: s.data as FormData,
    visitedSteps: new Set((s as unknown as { visitedSteps: string[] }).visitedSteps || []),
    validationErrors: [],
    isSubmitting: false,
    submitSuccess: false,
  })));
  const redoStack = useRef<FormState[]>(loadRedoHistory().map((s) => ({
    ...s,
    data: s.data as FormData,
    visitedSteps: new Set((s as unknown as { visitedSteps: string[] }).visitedSteps || []),
    validationErrors: [],
    isSubmitting: false,
    submitSuccess: false,
  })));

  const pushUndo = useCallback((currentState: FormState) => {
    undoStack.current = [...undoStack.current.slice(-29), { ...currentState, visitedSteps: new Set(currentState.visitedSteps) }];
    redoStack.current = [];
    saveUndoHistory(undoStack.current.map((s) => ({ data: s.data, currentStep: s.currentStep, timestamp: Date.now() })));
    saveRedoHistory([]);
  }, []);

  const canUndo = undoStack.current.length > 0;
  const canRedo = redoStack.current.length > 0;

  const undo = useCallback(() => {
    if (undoStack.current.length === 0) return;
    const prev = undoStack.current.pop()!;
    redoStack.current.push({ ...state, visitedSteps: new Set(state.visitedSteps) });
    dispatch({ type: 'RESTORE_STATE', state: { ...prev, visitedSteps: new Set(prev.visitedSteps) } });
    saveUndoHistory(undoStack.current.map((s) => ({ data: s.data, currentStep: s.currentStep, timestamp: Date.now() })));
    saveRedoHistory(redoStack.current.map((s) => ({ data: s.data, currentStep: s.currentStep, timestamp: Date.now() })));
  }, [state]);

  const redo = useCallback(() => {
    if (redoStack.current.length === 0) return;
    const next = redoStack.current.pop()!;
    undoStack.current.push({ ...state, visitedSteps: new Set(state.visitedSteps) });
    dispatch({ type: 'RESTORE_STATE', state: { ...next, visitedSteps: new Set(next.visitedSteps) } });
    saveUndoHistory(undoStack.current.map((s) => ({ data: s.data, currentStep: s.currentStep, timestamp: Date.now() })));
    saveRedoHistory(redoStack.current.map((s) => ({ data: s.data, currentStep: s.currentStep, timestamp: Date.now() })));
  }, [state]);

  const setField = useCallback((path: string, value: unknown) => {
    pushUndo(state);
    dispatch({ type: 'SET_FIELD', path, value });
  }, [state, pushUndo]);

  const goToStep = useCallback((step: StepId) => {
    pushUndo(state);
    dispatch({ type: 'GO_TO_STEP', step });
  }, [state, pushUndo]);

  const availableSteps = computeAvailableSteps(state.data);
  const currentStepIndex = availableSteps.indexOf(state.currentStep);

  const nextStep = useCallback(() => {
    const errors = validateStep(state.currentStep, state.data);
    if (errors.length > 0) {
      dispatch({ type: 'SET_VALIDATION_ERRORS', errors });
      return;
    }
    pushUndo(state);
    dispatch({ type: 'NEXT_STEP', availableSteps });
  }, [state, pushUndo, availableSteps]);

  const prevStep = useCallback(() => {
    pushUndo(state);
    dispatch({ type: 'PREV_STEP', availableSteps });
  }, [state, pushUndo, availableSteps]);

  const validateCurrentStep = useCallback((): ValidationError[] => {
    const errors = validateStep(state.currentStep, state.data);
    dispatch({ type: 'SET_VALIDATION_ERRORS', errors });
    return errors;
  }, [state.currentStep, state.data]);

  // Auto-save
  const autoSaveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
    if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current);
    autoSaveTimer.current = setTimeout(() => {
      saveDraft({ data: state.data, currentStep: state.currentStep, timestamp: Date.now() });
      saveVisitedSteps([...state.visitedSteps]);
    }, 500);
    return () => {
      if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current);
    };
  }, [state.data, state.currentStep, state.visitedSteps]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z' && !e.shiftKey) {
        e.preventDefault();
        undo();
      }
      if ((e.ctrlKey || e.metaKey) && e.key === 'z' && e.shiftKey) {
        e.preventDefault();
        redo();
      }
      if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
        e.preventDefault();
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  const contextValue: FormContextValue = {
    state,
    dispatch,
    goToStep,
    nextStep,
    prevStep,
    undo,
    redo,
    canUndo,
    canRedo,
    availableSteps,
    currentStepIndex,
    setField,
    validateCurrentStep,
  };

  return <FormContext.Provider value={contextValue}>{children}</FormContext.Provider>;
}

