import { useId, useRef, useState } from 'react';
import type { UploadedFile } from '../../types';

interface FileUploadProps {
  label: string;
  files: UploadedFile[];
  onAddFile: (file: UploadedFile) => void;
  onRemoveFile: (fileId: string) => void;
  error?: string;
  accept?: string;
  maxFiles?: number;
  maxSizeMB?: number;
  disabled?: boolean;
}

function fileToUploaded(file: File): Promise<UploadedFile> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      resolve({
        id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        name: file.name,
        size: file.size,
        type: file.type,
        dataUrl: reader.result as string,
      });
    };
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

export function FileUpload({
  label,
  files,
  onAddFile,
  onRemoveFile,
  error,
  accept = '*',
  maxFiles = 10,
  maxSizeMB = 10,
  disabled = false,
}: FileUploadProps) {
  const id = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const [uploadError, setUploadError] = useState<string>('');
  const errorId = `${id}-error`;
  const maxSizeBytes = maxSizeMB * 1024 * 1024;

  const handleChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = e.target.files;
    if (!selectedFiles) return;
    setUploadError('');

    if (files.length + selectedFiles.length > maxFiles) {
      setUploadError(`Maximum ${maxFiles} files allowed`);
      return;
    }

    const newFiles: UploadedFile[] = [];
    for (const file of Array.from(selectedFiles)) {
      if (file.size > maxSizeBytes) {
        setUploadError(`File "${file.name}" exceeds ${maxSizeMB}MB limit`);
        return;
      }
      try {
        const uploaded = await fileToUploaded(file);
        newFiles.push(uploaded);
      } catch {
        setUploadError(`Failed to read file "${file.name}"`);
        return;
      }
    }

    newFiles.forEach((f) => onAddFile(f));
    if (inputRef.current) inputRef.current.value = '';
  };

  const handleRemove = (fileId: string) => {
    onRemoveFile(fileId);
    setUploadError('');
  };

  const displayError = uploadError || error;

  return (
    <div className="form-field" role="group">
      <label htmlFor={id} className="form-label">
        {label}
      </label>
      <div className="file-upload-area">
        <input
          ref={inputRef}
          id={id}
          type="file"
          onChange={handleChange}
          accept={accept}
          multiple
          disabled={disabled || files.length >= maxFiles}
          aria-describedby={displayError ? errorId : undefined}
          aria-invalid={!!displayError}
          style={{
            position: 'absolute',
            width: '1px',
            height: '1px',
            padding: '0',
            margin: '-1px',
            overflow: 'hidden',
            clip: 'rect(0, 0, 0, 0)',
            whiteSpace: 'nowrap',
            border: '0',
          }}
        />
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          disabled={disabled || files.length >= maxFiles}
          className="btn btn--secondary"
          aria-label={`Upload file for ${label}`}
        >
          Choose file{files.length > 0 ? 's' : ''}
        </button>
        <span className="file-upload-hint" aria-live="polite">
          {files.length > 0
            ? `${files.length} file${files.length > 1 ? 's' : ''} selected`
            : `Max ${maxFiles} files, ${maxSizeMB}MB each`}
        </span>
      </div>
      {files.length > 0 && (
        <ul className="file-list" aria-label="Uploaded files">
          {files.map((f) => (
            <li key={f.id} className="file-list-item">
              <span className="file-name">{f.name}</span>
              <span className="file-size">({(f.size / 1024).toFixed(1)} KB)</span>
              <button
                type="button"
                onClick={() => handleRemove(f.id)}
                className="btn btn--danger btn--small"
                aria-label={`Remove ${f.name}`}
              >
                Remove
              </button>
            </li>
          ))}
        </ul>
      )}
      {displayError && (
        <p id={errorId} className="form-error" role="alert">
          {displayError}
        </p>
      )}
    </div>
  );
}

import { useRef, useState, useCallback, useEffect, useId } from 'react';
import type { SignatureData } from '../../types';

interface SignaturePadProps {
  label: string;
  value: SignatureData | null;
  onChange: (signature: SignatureData) => void;
  error?: string;
  required?: boolean;
  disabled?: boolean;
}

export function SignaturePad({
  label,
  value,
  onChange,
  error,
  required = false,
  disabled = false,
}: SignaturePadProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [hasSignature, setHasSignature] = useState(!!value?.dataUrl);
  const id = useId();
  const errorId = `${id}-error`;

  const getCanvasContext = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return null;
    return canvas.getContext('2d');
  }, []);

  const startDrawing = useCallback(
    (e: React.MouseEvent | React.TouchEvent | React.PointerEvent) => {
      if (disabled) return;
      const ctx = getCanvasContext();
      if (!ctx) return;

      const canvas = canvasRef.current!;
      const rect = canvas.getBoundingClientRect();
      let clientX: number, clientY: number;

      if ('touches' in e) {
        const touch = e.touches[0] || (e as React.TouchEvent).changedTouches[0];
        clientX = touch.clientX;
        clientY = touch.clientY;
      } else {
        clientX = (e as React.MouseEvent).clientX;
        clientY = (e as React.MouseEvent).clientY;
      }

      ctx.beginPath();
      ctx.moveTo(clientX - rect.left, clientY - rect.top);
      setIsDrawing(true);
    },
    [disabled, getCanvasContext]
  );

  const draw = useCallback(
    (e: React.MouseEvent | React.TouchEvent | React.PointerEvent) => {
      if (!isDrawing || disabled) return;
      const ctx = getCanvasContext();
      if (!ctx) return;

      const canvas = canvasRef.current!;
      const rect = canvas.getBoundingClientRect();
      let clientX: number, clientY: number;

      if ('touches' in e) {
        const touch = e.touches[0] || (e as React.TouchEvent).changedTouches[0];
        clientX = touch.clientX;
        clientY = touch.clientY;
      } else {
        clientX = (e as React.MouseEvent).clientX;
        clientY = (e as React.MouseEvent).clientY;
      }

      ctx.lineWidth = 2;
      ctx.lineCap = 'round';
      ctx.strokeStyle = '#000';
      ctx.lineTo(clientX - rect.left, clientY - rect.top);
      ctx.stroke();
    },
    [isDrawing, disabled, getCanvasContext]
  );

  const stopDrawing = useCallback(() => {
    if (!isDrawing) return;
    setIsDrawing(false);
    setHasSignature(true);

    const canvas = canvasRef.current;
    if (canvas && !canvas.toDataURL().includes('data:,')) {
      onChange({
        dataUrl: canvas.toDataURL(),
        signedAt: new Date().toISOString(),
      });
    }
  }, [isDrawing, onChange]);

  const clearSignature = useCallback(() => {
    const ctx = getCanvasContext();
    const canvas = canvasRef.current;
    if (ctx && canvas) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    setHasSignature(false);
    onChange({ dataUrl: '', signedAt: new Date().toISOString() });
  }, [getCanvasContext, onChange]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (disabled) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        if (hasSignature) {
          clearSignature();
        } else {
          // Simulate a simple signature for keyboard-only users
          const ctx = getCanvasContext();
          const canvas = canvasRef.current;
          if (ctx && canvas) {
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 2;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(20, canvas.height / 2);
            ctx.quadraticCurveTo(canvas.width / 2, 10, canvas.width - 20, canvas.height / 2);
            ctx.stroke();
            setHasSignature(true);
            onChange({
              dataUrl: canvas.toDataURL(),
              signedAt: new Date().toISOString(),
            });
          }
        }
      }
    },
    [disabled, hasSignature, clearSignature, getCanvasContext, onChange]
  );

  // Set canvas size
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const parent = canvas.parentElement;
    if (parent) {
      canvas.width = parent.clientWidth - 4;
      canvas.height = 150;
    }
  }, []);

  // Restore existing signature
  useEffect(() => {
    if (value?.dataUrl && canvasRef.current) {
      const img = new Image();
      img.onload = () => {
        const ctx = getCanvasContext();
        if (ctx) {
          ctx.drawImage(img, 0, 0);
          setHasSignature(true);
        }
      };
      img.src = value.dataUrl;
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <div className="form-field" role="group">
      <label className="form-label">
        {label}
        {required && <span className="required-asterisk" aria-hidden="true"> *</span>}
      </label>
      <div
        className={`signature-pad${error ? ' signature-pad--error' : ''}`}
        style={{
          border: `2px solid ${error ? '#dc3545' : '#ccc'}`,
          borderRadius: '4px',
          position: 'relative',
          touchAction: 'none',
        }}
      >
        <canvas
          ref={canvasRef}
          id={id}
          style={{
            display: 'block',
            width: '100%',
            height: '150px',
            cursor: disabled ? 'not-allowed' : 'crosshair',
          }}
          onPointerDown={startDrawing}
          onPointerMove={draw}
          onPointerUp={stopDrawing}
          onPointerLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
          role="img"
          aria-label={`Signature pad for ${label}. Press Enter or Space to toggle signature.`}
          tabIndex={0}
          onKeyDown={handleKeyDown}
          aria-required={required}
        />
        {hasSignature && !disabled && (
          <button
            type="button"
            onClick={clearSignature}
            className="btn btn--danger btn--small signature-clear-btn"
            aria-label="Clear signature"
          >
            Clear
          </button>
        )}
      </div>
      {error && (
        <p id={errorId} className="form-error" role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

